def _review_innerdicts_by_source_key(
    conn: duckdb.DuckDBPyConnection,
) -> dict[str, tuple[InnerDict, ...]]:
    grouped: defaultdict[str, list[InnerDict]] = defaultdict(list)
    relations_and_procedures = (
        (XLSX_MATCH_VIEW, XlsxMatchProcedure()),
        (PARQUET_LEGACY_ROWS_INNERDICT_TABLE, ParquetMatchProcedure()),
        (DOCX_MATCH_VIEW, DocxMatchProcedure()),
    )
    for relation, procedure in relations_and_procedures:
        cursor = conn.execute(f"SELECT * FROM {relation}")
        columns = [str(item[0]) for item in cursor.description]
        for values in cursor.fetchall():
            record = dict(zip(columns, values, strict=True))
            source_key = str(record.pop(KTP_SOURCE_KEY_COL))
            grouped[source_key].append(InnerDict.from_mapping(record, procedure))
    return {source_key: tuple(innerdicts) for source_key, innerdicts in grouped.items()}


