def _review_context_has_col(
    *,
    col: str,
    target_domain: str,
    domain_columns: dict[str, set[str]],
) -> bool:
    if col in {KTP_FILENAME_COL, KTP_FRAGMENT_COL, KTP_FRAGMENT_TYPE_COL}:
        return col in domain_columns[target_domain]
    return _review_info_domain(col) == target_domain and col in domain_columns[target_domain]


def _review_contract(
    conn: duckdb.DuckDBPyConnection,
) -> tuple[dict[str, set[str]], list[str]]:
    domain_column_lists = {
        domain: _relation_columns(conn, relation)
        for domain, relation in REVIEW_DOMAIN_RELATIONS.items()
    }
    domain_columns = {
        domain: set(columns) for domain, columns in domain_column_lists.items()
    }
    return domain_columns, _review_columns(domain_column_lists[REVIEW_DOMAIN_DOCX])


def _review_domain(inner: InnerDict) -> str:
    for domain, procedure_type in REVIEW_DOMAIN_PROCEDURES.items():
        if isinstance(inner.procedure, procedure_type):
            return domain
    raise ValueError(
        "Unsupported innerdict procedure in card partition review: "
        f"{type(inner.procedure).__name__}. Add its review domain explicitly."
    )


def _review_varchar(value: object) -> str | None:
    if value is None:
        return None
    try:
        if bool(pd.isna(value)):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)
    return str(value)


def _review_context_values(
    rows: list[InnerDict],
    *,
    source_col: str,
    source_columns: set[str],
) -> list[str]:
    order_cols: list[str] = []
    for col in (KTP_FILENAME_COL, KTP_FRAGMENT_COL, KTP_FRAGMENT_TYPE_COL, source_col):
        if col in source_columns and col not in order_cols:
            order_cols.append(col)

    values: list[tuple[tuple[tuple[bool, str], ...], str]] = []
    for inner in rows:
        value = _review_varchar(inner.data.get(source_col))
        if value is None or not value.strip():
            continue
        order_key = tuple(
            (order_value is None, "" if order_value is None else order_value)
            for col in order_cols
            for order_value in [_review_varchar(inner.data.get(col))]
        )
        values.append((order_key, value))
    values.sort(key=lambda item: item[0])
    return [value for _order_key, value in values]


def _review_contexts(
    domain_rows: dict[str, list[InnerDict]],
    *,
    domain_columns: dict[str, set[str]],
    columns: list[str],
) -> dict[str, dict[str, list[str]]]:
    contexts: dict[str, dict[str, list[str]]] = {}
    for domain, rows in domain_rows.items():
        contexts[domain] = {
            col: _review_context_values(
                rows,
                source_col=col,
                source_columns=domain_columns[domain],
            )
            for col in columns
            if _review_context_has_col(
                col=col,
                target_domain=domain,
                domain_columns=domain_columns,
            )
        }
    return contexts


def _merge_review_values(values: list[str]) -> str | None:
    if not values:
        return None
    separator = (
        "\n-----\n"
        if any("\n" in value or "\r" in value for value in values)
        else "\n"
    )
    return separator.join(values)


def _review_context_value(
    contexts: dict[str, dict[str, list[str]]],
    *,
    domain: str,
    col: str,
) -> str | None:
    return _merge_review_values(contexts[domain].get(col, []))


def _review_row(
    partition_row: dict[str, object],
    *,
    primary_domain: str | None,
    primary_inner: InnerDict | None,
    contexts: dict[str, dict[str, list[str]]],
    domain_columns: dict[str, set[str]],
    columns: list[str],
) -> dict[str, object]:
    partition_flags = {
        KTP_PARTITION_FLAG_XLSX_NON_EXACT_ANY_COL,
        KTP_PARTITION_FLAG_XLSX_ANY_COL,
        KTP_PARTITION_FLAG_SSN_COUNT_COL,
        KTP_PARTITION_FLAG_DOCX_TABLE_1_REQUIRED_ALL_COL,
        KTP_PARTITION_FLAG_DOCX_ANY_COL,
    }
    row: dict[str, object] = {}
    for col in columns:
        if col in {KTP_SOURCE_KEY_COL, KTP_PARTITION_COL} | partition_flags:
            row[col] = partition_row[col]
        elif col == KTP_FF_AUTHOR_ID_COL:
            if (
                primary_domain == REVIEW_DOMAIN_SCISCINET
                and primary_inner is not None
                and KTP_FRAGMENT_COL in domain_columns[REVIEW_DOMAIN_SCISCINET]
            ):
                row[col] = _review_varchar(primary_inner.data.get(KTP_FRAGMENT_COL))
            else:
                row[col] = _review_context_value(
                    contexts,
                    domain=REVIEW_DOMAIN_SCISCINET,
                    col=KTP_FRAGMENT_COL,
                )
        elif col in {KTP_FF_DISCARD_COL, KTP_FF_NOTE_COL}:
            row[col] = None
        elif col in {KTP_FILENAME_COL, KTP_FRAGMENT_COL, KTP_FRAGMENT_TYPE_COL}:
            values = [
                value
                for domain in (
                    REVIEW_DOMAIN_XLSX,
                    REVIEW_DOMAIN_SCISCINET,
                    REVIEW_DOMAIN_DOCX,
                )
                for value in contexts[domain].get(col, [])
            ]
            row[col] = _merge_review_values(values)
        elif col in {DRAW_LABEL, KTP_FIRST_NAME_COL, KTP_LAST_NAME_COL}:
            row[col] = _review_varchar(partition_row[col])
        elif (domain := _review_info_domain(col)) is not None:
            row[col] = _review_context_value(contexts, domain=domain, col=col)
        else:
            row[col] = None
    return row


def _build_partition_review_rows_df(
    partition_df: pd.DataFrame,
    *,
    innerdicts_by_source_key: dict[str, tuple[InnerDict, ...]],
    domain_columns: dict[str, set[str]],
    columns: list[str],
) -> pd.DataFrame:
    records: list[dict[str, object]] = []
    partition_domains = {
        KTP_PARTITION_XLSX_VALUE: REVIEW_DOMAIN_XLSX,
        KTP_PARTITION_SSN_VALUE: REVIEW_DOMAIN_SCISCINET,
        KTP_PARTITION_DOCX_VALUE: REVIEW_DOMAIN_DOCX,
    }
    for partition_row in partition_df.to_dict("records"):
        source_key = str(partition_row[KTP_SOURCE_KEY_COL])
        domain_rows: dict[str, list[InnerDict]] = {
            REVIEW_DOMAIN_XLSX: [],
            REVIEW_DOMAIN_SCISCINET: [],
            REVIEW_DOMAIN_DOCX: [],
        }
        for inner in innerdicts_by_source_key.get(source_key, ()):
            domain_rows[_review_domain(inner)].append(inner)
        contexts = _review_contexts(
            domain_rows,
            domain_columns=domain_columns,
            columns=columns,
        )

        partition = int(partition_row[KTP_PARTITION_COL])
        primary_domain = partition_domains.get(partition)
        primary_rows: list[InnerDict | None]
        if primary_domain is None:
            primary_rows = [None]
        else:
            primary_rows = domain_rows[primary_domain] or [None]
        for primary_inner in primary_rows:
            records.append(
                _review_row(
                    partition_row,
                    primary_domain=primary_domain,
                    primary_inner=primary_inner,
                    contexts=contexts,
                    domain_columns=domain_columns,
                    columns=columns,
                )
            )
    return pd.DataFrame(records, columns=columns)


def _review_column_type(col: str) -> str:
    if col in {KTP_PARTITION_COL, KTP_PARTITION_FLAG_SSN_COUNT_COL}:
        return "BIGINT"
    if col in {
        KTP_FF_DISCARD_COL,
        KTP_PARTITION_FLAG_XLSX_NON_EXACT_ANY_COL,
        KTP_PARTITION_FLAG_XLSX_ANY_COL,
        KTP_PARTITION_FLAG_DOCX_TABLE_1_REQUIRED_ALL_COL,
        KTP_PARTITION_FLAG_DOCX_ANY_COL,
    }:
        return "BOOLEAN"
    return "VARCHAR"


def _materialize_partition_review_rows_table(
    conn: duckdb.DuckDBPyConnection,
    review_df: pd.DataFrame,
    *,
    columns: list[str],
) -> None:
    definitions = ", ".join(
        f"{duckdb_quote_identifier(col)} {_review_column_type(col)}" for col in columns
    )
    if review_df.empty:
        conn.execute(
            f"CREATE OR REPLACE TABLE {CARD_PARTITION_REVIEW_ROWS_TABLE} "
            f"({definitions})"
        )
        return

    register_frame(conn, CARD_PARTITION_REVIEW_FRAME_TABLE, review_df)
    try:
        projection = ", ".join(
            f"CAST({duckdb_quote_identifier(col)} AS {_review_column_type(col)}) "
            f"AS {duckdb_quote_identifier(col)}"
            for col in columns
        )
        conn.execute(
            f"CREATE OR REPLACE TABLE {CARD_PARTITION_REVIEW_ROWS_TABLE} AS "
            f"SELECT {projection} FROM {CARD_PARTITION_REVIEW_FRAME_TABLE}"
        )
    finally:
        conn.execute(f"DROP TABLE IF EXISTS {CARD_PARTITION_REVIEW_FRAME_TABLE}")


def _create_partition_review_view(
    conn: duckdb.DuckDBPyConnection,
    *,
    columns: list[str],
) -> None:
    select_columns = ",\n            ".join(duckdb_quote_identifier(col) for col in columns)
    conn.execute(
        f"""
        CREATE OR REPLACE VIEW {CARD_PARTITION_REVIEW_VIEW} AS
        WITH
        base AS (
            SELECT *
            FROM {CARD_PARTITION_REVIEW_ROWS_TABLE}
        ),
        {draw_sort_ctes_sql(draw_col=DRAW_LABEL, source_key_col=KTP_SOURCE_KEY_COL)}
        SELECT
            {select_columns}
        FROM ranked
        ORDER BY
            CASE "{KTP_PARTITION_COL}"
                WHEN {KTP_PARTITION_XLSX_VALUE} THEN 0
                WHEN {KTP_PARTITION_SSN_VALUE} THEN 1
                WHEN {KTP_PARTITION_DOCX_VALUE} THEN 2
                ELSE 3
            END,
            CASE
                WHEN "{KTP_PARTITION_COL}" = {KTP_PARTITION_SSN_VALUE}
                    THEN "{KTP_PARTITION_FLAG_SSN_COUNT_COL}"
                ELSE 0
            END,
            CASE
                WHEN "{KTP_PARTITION_COL}" = {KTP_PARTITION_SSN_VALUE}
                 AND "{KTP_PARTITION_FLAG_XLSX_ANY_COL}"
                 AND NOT "{KTP_PARTITION_FLAG_XLSX_NON_EXACT_ANY_COL}"
                    THEN 0
                WHEN "{KTP_PARTITION_COL}" = {KTP_PARTITION_SSN_VALUE}
                    THEN 1
                ELSE 0
            END,
            {draw_sort_order_by_sql(
                source_key_col=KTP_SOURCE_KEY_COL,
                filename_col=KTP_FILENAME_COL,
                fragment_col=KTP_FRAGMENT_COL,
            )}
        """
    )


def _materialize_partition_review(
    conn: duckdb.DuckDBPyConnection,
    partition_df: pd.DataFrame,
    *,
    innerdicts_by_source_key: dict[str, tuple[InnerDict, ...]],
) -> list[str]:
    domain_columns, columns = _review_contract(conn)
    review_df = _build_partition_review_rows_df(
        partition_df,
        innerdicts_by_source_key=innerdicts_by_source_key,
        domain_columns=domain_columns,
        columns=columns,
    )
    _materialize_partition_review_rows_table(conn, review_df, columns=columns)
    _create_partition_review_view(conn, columns=columns)
    return columns


def _build_selected_outer_dict(
    selected_items: list[tuple[NameKey, tuple[InnerDict, ...]]]
) -> OuterDict:
    subset_outer = OuterDict.from_name_keys([name_key for name_key, _ in selected_items])
    for name_key, inner_dicts in selected_items:
        for inner in inner_dicts:
            subset_outer.add_inner(name_key, inner)
    return subset_outer


